  set(7,1);    // Canada Day
  set(9,30);   // National Day for Truth and Reconciliation
  set(11,11);  // Remembrance Day
  set(12,25);  // Christmas Day
  set(12,26);  // Boxing Day
  set(5, lastMondayOnBefore(5,24)); // Victoria Day
  set(8, nthMonday(8,1));           // Civic Holiday (1st Mon Aug)
  set(9, nthMonday(9,1));           // Labour Day (1st Mon Sep)
  set(10, nthMonday(10,2));         // Thanksgiving (2nd Mon Oct)
  // Good Friday & Easter Monday (Anonymous Gregorian algorithm)
